public Task<string> GetDataAsync()
{
    var stateMachine = new GetDataAsyncStateMachine();
    stateMachine.builder = AsyncTaskMethodBuilder<string>.Create();
    stateMachine.state = -1;
    stateMachine.builder.Start(ref stateMachine);
    return stateMachine.builder.Task;
}

private struct GetDataAsyncStateMachine : IAsyncStateMachine
{
    public int state;
    public AsyncTaskMethodBuilder<string> builder;
    private HttpClient client;
    private HttpResponseMessage response;
    private TaskAwaiter<HttpResponseMessage> awaiter;

    public void MoveNext()
    {
        try
        {
            if (state == -1)
            {
                client = new HttpClient();
                var task = client.GetAsync("https://api.example.com/data");
                awaiter = task.GetAwaiter();
                if (!awaiter.IsCompleted)
                {
                    state = 0;
                    builder.AwaitUnsafeOnCompleted(ref awaiter, ref this);
                    return;
                }
            }
            response = awaiter.GetResult();
            var readTask = response.Content.ReadAsStringAsync();
            var readAwaiter = readTask.GetAwaiter();
            if (!readAwaiter.IsCompleted)
            {
                state = 1;
                builder.AwaitUnsafeOnCompleted(ref readAwaiter, ref this);
                return;
            }
            var result = readAwaiter.GetResult();
            state = -2;
            builder.SetResult(result);
        }
        catch (Exception ex)
        {
            state = -2;
            builder.SetException(ex);
        }
    }
}

