// Use ValueTask when:
// 1. The operation often completes synchronously
// 2. The method is called in a tight loop
// 3. You want to avoid allocations

public ValueTask<int> GetValueAsync()
{
    // Fast path: cached value
    if (_cachedValue.HasValue)
    {
        return new ValueTask<int>(_cachedValue.Value);
    }

    // Slow path: async operation
    return new ValueTask<int>(LoadValueAsync());
}

private async Task<int> LoadValueAsync()
{
    await Task.Delay(100);
    _cachedValue = 42;
    return _cachedValue.Value;
}

// ❌ Sequential await (slow)
public async Task<List<string>> GetDataSequential()
{
    var results = new List<string>();
    foreach (var url in urls)
    {
        var data = await client.GetStringAsync(url);
        results.Add(data);
    }
    return results;
}

// ✅ Concurrent with Task.WhenAll (fast)
public async Task<List<string>> GetDataConcurrent()
{
    var tasks = urls.Select(url => client.GetStringAsync(url));
    var results = await Task.WhenAll(tasks);
    return results.ToList();
}

// ✅ With degree of parallelism control
public async Task<List<string>> GetDataConcurrentBounded()
{
    var semaphore = new SemaphoreSlim(10); // Max 10 concurrent
    var tasks = urls.Select(async url =>
    {
        await semaphore.WaitAsync();
        try
        {
            return await client.GetStringAsync(url);
        }
        finally
        {
            semaphore.Release();
        }
    });
    return (await Task.WhenAll(tasks)).ToList();
}

